package com.cloudticket.promotion.redis;
import com.cloudticket.promotion.persistence.entity.CouponEntity; import java.util.List; import org.springframework.core.io.ClassPathResource; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.data.redis.core.script.DefaultRedisScript; import org.springframework.stereotype.Service;
@Service public class CouponClaimService { private final StringRedisTemplate redis; private final DefaultRedisScript<Long> script; public CouponClaimService(StringRedisTemplate redis){this.redis=redis;this.script=new DefaultRedisScript<>();this.script.setLocation(new ClassPathResource("redis/claim-coupon.lua"));this.script.setResultType(Long.class);}
 public void claim(CouponEntity coupon,String userId){String stock="promotion:coupon:stock:"+coupon.getId(), members="promotion:coupon:members:"+coupon.getId(), counts="promotion:coupon:user-count:"+coupon.getId()+":"+userId; if(Boolean.FALSE.equals(redis.hasKey(stock))) redis.opsForValue().setIfAbsent(stock,String.valueOf(Math.max(0,coupon.getTotalCount()-coupon.getIssuedCount()))); Long result=redis.execute(script,List.of(stock,members,counts),userId,String.valueOf(Math.max(1,coupon.getUserLimit()))); if(result==null||result<0) throw new IllegalStateException(switch(result==null?-9:result.intValue()){case -1->"coupon stock unavailable";case -2->"coupon sold out";case -3->"coupon already claimed";case -4->"coupon user limit reached";default->"coupon claim failed";}); }
}
